Theorem fse_build_proofA : forall AI : AMallocIface, fse_build_stmtA AI.
Proof.
intros AI. unfold fse_build_stmtA.
intros L RNG ra gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 FR fc m st LB SPV DT NC WK wks msv tl nc jdt jw d lo
  BD MSV0 WKS AH LBB DTA LJD WKA LJW NCB NCR HDT HWK HNC DT4 WK2 NC2 SHADOW SDN SWN ST BOT LO SPT SP16 MI RST RI.
pose proof (build_dtable_inv nc msv tl wks d BD MSV0) as (TLR & MSVR & _).
assert (P2 : 2 <= 2^tl <= 4096) by (split; [apply (Z.pow_le_mono_r 2 1 tl); lia | apply (Z.pow_le_mono_r 2 tl 12); lia]).
assert (SZD : 0 <= FSE_DTABLE_SIZE tl) by (unfold FSE_DTABLE_SIZE; lia).
assert (SZW : 0 <= FSE_BUILD_DTABLE_WKSP_SIZE tl msv) by (unfold FSE_BUILD_DTABLE_WKSP_SIZE; lia).
assert (SZN : 0 <= 2 * zlen nc) by lia.
pose proof (AI_layout AI L RNG st LB m AH) as (_ & _ & ATL & _).
pose proof (AH_huf_kit.fse_rt_of_aheap AI L RNG st LB m AH) as (GOT & _ & _ & SHB & _).
destruct (hblk8_block _ _ _ HDT) as (bD & InD & bD1 & bD2).
destruct (hblk8_block _ _ _ HWK) as (bW & InW & bW1 & bW2).
destruct (hblk8_block _ _ _ HNC) as (bN & InN & bN1 & bN2).
assert (BDT : ablk DT (DT + FSE_DTABLE_SIZE tl)) by (apply (ablk_sub _ _ _ _ (LBB bD InD)); lia).
assert (BWK : ablk WK (WK + FSE_BUILD_DTABLE_WKSP_SIZE tl msv)) by (apply (ablk_sub _ _ _ _ (LBB bW InW)); lia).
assert (BNC : ablk NC (NC + 2 * zlen nc)) by (apply (ablk_sub _ _ _ _ (LBB bN InN)); lia).
pose proof (zshadow_of_hblk8 AI L RNG st LB m _ _ AH HDT SZD) as ZD.
pose proof (zshadow_of_hblk8 AI L RNG st LB m _ _ AH HWK SZW) as ZW.
pose proof (zshadow_of_hblk8 AI L RNG st LB m _ _ AH HNC SZN) as ZN.
pose proof (rng_of_hblk8 AI L RNG st LB m _ _ AH HDT SZD) as (RD & RDS).
pose proof (rng_of_hblk8 AI L RNG st LB m _ _ AH HWK SZW) as (RW & RWS).
pose proof (rng_of_hblk8 AI L RNG st LB m _ _ AH HNC SZN) as (RN & RNS).
assert (SPT' : SPV + 16 < 2^47) by lia.
assert (RSTK : rng RNG lo (SPV - lo)) by (apply (rng_sub _ _ _ _ _ RST); lia).
eapply evtF_mono; [eapply fse_build_coreA; eassumption |].
intros ms' (t0' & t1' & t2' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m' & -> & MU & WM & MI' & ST' & UD).
unfold fse_build_postA. do 15 eexists. split; [reflexivity|].
split; [exact MI'|]. split; [exact ST'|]. split; [| split; [| exact UD]].
- eapply AH_huf_kit.magree_munch_step; [apply magree_refl | exact MU | exact WM |].
  intros a (CA & ND & NW). cbn [outside]. split; [| split; [exact ND | split; [exact NW | exact I]]].
  intros HA. apply (AH_huf_kit.stack_not_client (aci AI) LB SPV (SPV - AFSE_BUILD_STACK) a (AI_aci_img AI) (AI_aci_lo AI) LBB);
    [ | exact HA | exact CA].
  unfold AFSE_BUILD_STACK in *. pose proof atop_range. lia.
- eapply AI_frame; [exact AH | exact MU | exact WM |].
  apply Forall_cons; [| apply Forall_cons; [| apply Forall_cons; [| apply Forall_nil]]]; cbn [fst snd].
  + apply AH_huf_kit.cr_stack; unfold AFSE_BUILD_STACK in *; lia.
  + apply (AH_huf_kit.cr_block _ _ _ _ _ bD InD); lia.
  + apply (AH_huf_kit.cr_block _ _ _ _ _ bW InW); lia.
Qed.
End CANSEC1.
